rust.examples/shapes.rs:
use serde::{Deserialize, Serialize};

// the default: the variant name wraps the data
#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
enum Wrapped {
    Circle { radius: f64 },
    Square { side: f64 },
}

// tag = "type": the variant name becomes a field inside the object
#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "lowercase")]
enum Tagged {
    Circle { radius: f64 },
    Square { side: f64 },
}

fn main() -> Result<(), serde_json::Error> {
    println!("{}", serde_json::to_string(&Wrapped::Circle { radius: 1.5 })?);
    println!("{}", serde_json::to_string(&Tagged::Circle { radius: 1.5 })?);

    let shapes: Vec<Tagged> =
        serde_json::from_str(r#"[{"type":"circle","radius":2.0},{"type":"square","side":3.0}]"#)?;
    println!("{shapes:?}");

    // an unknown tag is an error, not a guess
    let err = serde_json::from_str::<Tagged>(r#"{"type":"triangle","side":3.0}"#).unwrap_err();
    println!("error: {err}");
    Ok(())
}

rust.examples/strict.rs:
use serde::Deserialize;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct Person {
    full_name: String,
    age: u32,
}

fn main() {
    let inputs = [
        r#"{ "fullName": "Ana", "age": 31, "nickname": "A" }"#, // unknown field
        r#"{ "fullName": "Bo", "age": "28" }"#,                  // a string, not a number
        r#"{ "fullName": "Cy", "age": -1 }"#,                    // negative for a u32
        r#"{ "fullName": "Di", "age": 1.5 }"#,                   // fraction for a u32
        r#"{ "fullName": "Ed", "age": 40"#,                      // cut off
    ];
    for text in inputs {
        match serde_json::from_str::<Person>(text) {
            Ok(p) => println!("ok: {} is {}", p.full_name, p.age),
            Err(e) => println!("error: {e}"),
        }
    }
}

rust.examples/untyped.rs:
use serde_json::{Value, json};

fn main() -> Result<(), serde_json::Error> {
    // no struct: parse into serde_json::Value and look things up by key
    let v: Value = serde_json::from_str(r#"{ "fullName": "Ana", "tags": ["admin", "dev"] }"#)?;
    println!("{}", v["fullName"]);
    println!("{}", v["tags"][1]);
    println!("{}", v["nope"]); // a missing key is Value::Null, not an error
    println!("{:?}", v["fullName"].as_str());
    println!("{:?}", v["fullName"].as_u64());

    // build JSON with the json! macro
    let out = json!({ "ok": true, "count": 2, "names": ["Ana", "Bo"] });
    println!("{out}");
    Ok(())
}

